{
  "id": "investigate",
  "label": "Investigate",
  "description": "Read-only diagnosis that gathers evidence, identifies root cause or trade-offs, and reports a cited conclusion.",
  "when_to_use": "Use when the task is to understand, triage, or explain something without changing files.",
  "steps": [
    {
      "key": "scope",
      "label": "Define the question",
      "phase": "setup",
      "guidance": "Restate the question, constraints, and what evidence would answer it. Do not edit files."
    },
    {
      "key": "inspect",
      "label": "Inspect evidence",
      "phase": "analysis",
      "guidance": "Read relevant code, docs, logs, or configuration. Prefer primary sources and record file paths or commands used."
    },
    {
      "key": "verify",
      "label": "Challenge the conclusion",
      "phase": "review",
      "guidance": "Look for contradictory evidence and alternative explanations before settling on an answer."
    },
    {
      "key": "report",
      "label": "Report findings",
      "phase": "handoff",
      "guidance": "Deliver a bounded report stating the conclusion, auditable evidence, remaining uncertainty, and suggested next steps. Confirm workspace preservation from the actions taken and available evidence. Mark this step complete only after that report has been delivered; a completion check is not a substitute for the report."
    }
  ],
  "guards": []
}
